import "core-js/modules/es.array.push.js";
import "core-js/modules/esnext.iterator.constructor.js";
import "core-js/modules/esnext.iterator.filter.js";
import "core-js/modules/esnext.iterator.for-each.js";
import { ref, computed, onMounted } from "vue";
import { collection, getDocs, addDoc, updateDoc, deleteDoc, doc, Timestamp } from "firebase/firestore";
import { db, storage } from "../firebase";
import { ref as storageRef, uploadBytes, getDownloadURL } from "firebase/storage";
export default {
  name: "InvitationToBid",
  setup() {
    const invitations = ref([]);
    const searchQuery = ref("");
    const showCreateForm = ref(false);
    const createForm = ref({
      projectName: "",
      projectDescription: "",
      location: "",
      abcCost: "",
      deadline: "",
      pdfFile: null,
      supportingDocs: null,
      timerDuration: ""
    });
    const editForm = ref({});
    const showViewModal = ref(false);
    const showEditModal = ref(false);
    const showDeleteModal = ref(false);
    const currentInvitation = ref(null);
    const filteredInvitations = computed(() => invitations.value.filter(inv => !inv.archived && inv.projectName.toLowerCase().includes(searchQuery.value.toLowerCase())));
    const archivedInvitations = computed(() => invitations.value.filter(inv => inv.archived));
    const fetchInvitations = async () => {
      const querySnapshot = await getDocs(collection(db, "invitations"));
      invitations.value = [];
      querySnapshot.forEach(docSnap => {
        const data = docSnap.data();
        invitations.value.push({
          id: docSnap.id,
          ...data
        });
      });

      // Auto-archive expired invitations
      const now = new Date();
      for (let inv of invitations.value) {
        if (inv.expiresAt) {
          const expires = inv.expiresAt.toDate();
          if (expires <= now && !inv.archived) {
            const docRef = doc(db, "invitations", inv.id);
            await updateDoc(docRef, {
              archived: true,
              archivedAt: new Date()
            });
          }
        }
      }
    };
    const handleFileUpload = (event, target, key) => {
      if (event.target.files.length) {
        target[key] = event.target.files[0];
      }
    };
    const createInvitation = async () => {
      if (!createForm.value.projectName || !createForm.value.deadline) {
        showNotification("Please fill in all required fields", true);
        return;
      }
      const expiresAt = new Date();
      expiresAt.setMinutes(expiresAt.getMinutes() + Number(createForm.value.timerDuration || 0));
      const pdfUrl = createForm.value.pdfFile ? await uploadFile(createForm.value.pdfFile) : "";
      const docsUrl = createForm.value.supportingDocs ? await uploadFile(createForm.value.supportingDocs) : "";
      await addDoc(collection(db, "invitations"), {
        ...createForm.value,
        pdfUrl,
        docsUrl,
        expiresAt: Timestamp.fromDate(expiresAt),
        archived: false,
        archivedAt: null
      });
      showNotification("Invitation created successfully!");
      showCreateForm.value = false;
      createForm.value = {
        projectName: "",
        projectDescription: "",
        location: "",
        abcCost: "",
        deadline: "",
        pdfFile: null,
        supportingDocs: null,
        timerDuration: ""
      };
      await fetchInvitations();
    };
    const uploadFile = async file => {
      const fileRef = storageRef(storage, `invitations/${file.name}`);
      await uploadBytes(fileRef, file);
      return await getDownloadURL(fileRef);
    };
    const updateInvitationModal = inv => {
      editForm.value = {
        ...inv
      };
      showEditModal.value = true;
    };
    const updateInvitation = async () => {
      const expiresAt = new Date();
      expiresAt.setMinutes(expiresAt.getMinutes() + Number(editForm.value.timerDuration || 0));
      const updates = {
        ...editForm.value,
        expiresAt: Timestamp.fromDate(expiresAt)
      };
      if (editForm.value.pdfFile instanceof File) {
        updates.pdfUrl = await uploadFile(editForm.value.pdfFile);
      }
      if (editForm.value.supportingDocs instanceof File) {
        updates.docsUrl = await uploadFile(editForm.value.supportingDocs);
      }
      const docRef = doc(db, "invitations", editForm.value.id);
      await updateDoc(docRef, updates);
      showNotification("Invitation updated successfully!");
      showEditModal.value = false;
      await fetchInvitations();
    };
    const deleteInvitationModal = inv => {
      currentInvitation.value = inv;
      showDeleteModal.value = true;
    };
    const deleteInvitation = async () => {
      await deleteDoc(doc(db, "invitations", currentInvitation.value.id));
      showNotification("Invitation deleted successfully!");
      showDeleteModal.value = false;
      await fetchInvitations();
    };
    const restoreInvitation = async inv => {
      const newMinutes = prompt("Enter new timer duration in minutes:", "60");
      if (!newMinutes || isNaN(newMinutes)) return;
      const expiresAt = new Date();
      expiresAt.setMinutes(expiresAt.getMinutes() + Number(newMinutes));
      const docRef = doc(db, "invitations", inv.id);
      await updateDoc(docRef, {
        archived: false,
        archivedAt: null,
        timerDuration: Number(newMinutes),
        expiresAt: Timestamp.fromDate(expiresAt)
      });
      showNotification("Invitation restored with new timer!");
      await fetchInvitations();
    };
    const getTimeLeft = inv => {
      if (!inv.expiresAt) return "No timer";
      const now = new Date();
      const expires = inv.expiresAt.toDate();
      const diff = expires - now;
      if (diff <= 0) return "Expired";
      const minutes = Math.floor(diff / 60000);
      const seconds = Math.floor(diff % 60000 / 1000);
      return `${minutes}m ${seconds}s`;
    };
    const isDeadlineSoon = deadline => {
      const now = new Date();
      const diff = new Date(deadline) - now;
      return diff > 0 && diff <= 24 * 60 * 60 * 1000;
    };
    const showNotification = (message, isError = false) => {
      const notif = document.createElement("div");
      notif.textContent = message;
      notif.className = `notification ${isError ? "error" : "success"}`;
      document.body.appendChild(notif);
      setTimeout(() => {
        notif.remove();
      }, 3000);
    };
    onMounted(fetchInvitations);
    return {
      invitations,
      searchQuery,
      showCreateForm,
      createForm,
      editForm,
      showViewModal,
      showEditModal,
      showDeleteModal,
      currentInvitation,
      filteredInvitations,
      archivedInvitations,
      handleFileUpload,
      createInvitation,
      updateInvitationModal,
      updateInvitation,
      deleteInvitationModal,
      deleteInvitation,
      restoreInvitation,
      getTimeLeft,
      isDeadlineSoon
    };
  }
};
